(32016, 'Psalms 39:11', 'Psalms', 39, 11, 'په سبب زمونږ د خپلو ګناهونو راکوې سزا ته مونږ ته په رټلو هغه څه چې خوښوو مونږ هغه ته بربادوې لکه حشرې په شان په رښتیا چې مونږ پوکی یو بل څه نه یو', 'په سبب زمونز د خپلو ګناهونو راکوې سزا ته مونز ته په رتلو هغه چه چې خوشوو مونز هغه ته بربادوې لکه حشرې په شان په رشتیا چې مونز پوکی یو بل چه نه یو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_39_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32017, 'Psalms 39:12', 'Psalms', 39, 12, 'ای څښتنه، ته دعا واوره زما غوږ دې ونیسه فریاد ته ته زما هغه وخت چې زه ژړا کړم نو کومک لره مې راشه زه د څو شېبو دپاره ستا مېلمه یم لکه څنګه چې نیکونه وو زما', 'ای چشتنه، ته دعا واوره زما غوز دې ونیسه فریاد ته ته زما هغه وخت چې زه ژرا کرم نو کومک لره مې راشه زه د چو شېبو دپاره ستا مېلمه یم لکه چنګه چې نیکونه وو زما', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_39_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32018, 'Psalms 39:13', 'Psalms', 39, 13, 'مخکې له دې نه چې زه مړ شم او نور پاتې نه شم یوازې پرېږده ما ترڅو چې لږ خوشحاله شمه', 'مخکې له دې نه چې زه مر شم او نور پاتې نه شم یوازې پرېزده ما ترچو چې لز خوشحاله شمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_39_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32019, 'Numbers 25:1', 'Numbers', 25, 1, 'کله چې اسراییلیان په شطیم کې اوسېدل، ځینو سړیو د موآبي ښځو سره زنا کول پیل کړل.', 'کله چې اسراییلیان په شطیم کې اوسېدل، جینو سریو د موابی شجو سره زنا کول پیل کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32020, 'Numbers 25:2', 'Numbers', 25, 2, 'دغو ښځو بیا هغه سړي هغو مراسمو ته راوبلل چې د هغوی خدایانو ته په کې نذرانې وړاندې کېدلې. د اسراییلو خلکو د قربانیو غوښه وخوړله او د موآبي خدایانو عبادت یې وکړ.', 'دغو شجو بیا هغه سری هغو مراسمو ته راوبلل چې د هغوی خدایانو ته په کې نذرانې وراندې کېدلې. د اسراییلو خلکو د قربانیو غوشه وخورله او د موابی خدایانو عبادت یې وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32021, 'Numbers 25:3', 'Numbers', 25, 3, 'څښتن په اسراییلیانو باندې په قهر شو، ځکه چې هغوی د بعل فغور د بت عبادت کړی ؤ.', 'چشتن په اسراییلیانو باندې په قهر شو، جکه چې هغوی د بعل فغور د بت عبادت کری و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32022, 'Numbers 25:4', 'Numbers', 25, 4, 'نو هغه موسی ته وویل: «د اسراییلو ټول مشران بوځه او په رڼا ورځ یې زما په حضور کې اعدام کړه، بیا به زما سخت قهر په اسراییلیانو باندې سوړ شي.»', 'نو هغه موسی ته وویل: «د اسراییلو تول مشران بوجه او په رنا ورج یې زما په حضور کې اعدام کره، بیا به زما سخت قهر په اسراییلیانو باندې سور شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32023, 'Numbers 25:5', 'Numbers', 25, 5, 'موسی هغو اسراییلیانو ته چې د قاضیانو په توګه یې کار کاوه وویل: «تاسو هر یو باید د خپلې قبیلې هغه کس ووژنئ چې د بعل فغور عبادت یې کړی دی.»', 'موسی هغو اسراییلیانو ته چې د قاضیانو په توګه یې کار کاوه وویل: «تاسو هر یو باید د خپلې قبیلې هغه کس ووژنی چې د بعل فغور عبادت یې کری دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(32024, 'Numbers 25:6', 'Numbers', 25, 6, 'یو اسراییلي سړي د موسی او ټول قوم په مخکې چې هغوی د سپېڅلې خېمې په دروازه کې ژړل، یوه مدیانۍ ښځه خپلې خېمې ته راوستله.', 'یو اسراییلی سری د موسی او تول قوم په مخکې چې هغوی د سپېچلې خېمې په دروازه کې ژرل، یوه مدیانی شجه خپلې خېمې ته راوستله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(32025, 'Numbers 25:7', 'Numbers', 25, 7, 'د العازار زوی او د هارون کاهن لمسي فینحاس هغه ولیدل او د خلکو د ګڼې ګوڼې څخه لاړ. هغه یوه نېزه راواخیستله', 'د العازار زوی او د هارون کاهن لمسی فینحاس هغه ولیدل او د خلکو د ګنې ګونې چخه لار. هغه یوه نېزه راواخیستله', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_25_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
